/**
 * Every mail of the product. Each template returns { subject, element }; the plain-text
 * version is generated by React Email from the same element.
 */
import { contactEmail } from '@/lib/contact';
import { appUrl, Code, CTA, H1, Layout, MailBrand, P, Quote } from './Layout';

export type Mail = { subject: string; element: React.ReactElement };

/** « 482913 » → « 482 913 ». */
const spaced = (code: string) => `${code.slice(0, 3)} ${code.slice(3)}`;

/**
 * The code first, the link as a fallback (« Se connecter sur cet appareil »): mail scanners of
 * university inboxes open links before the person does, and a mail read on a phone must still
 * log in the computer.
 */
function CodeBlock({ code, cta, url }: { code: string; cta: string; url: string }) {
  return (
    <>
      <P>Ton code :</P>
      <Code>{spaced(code)}</Code>
      <P muted>
        Saisis-le sur la page ouverte sur ton ordinateur ou ton téléphone. Il est valable 10
        minutes. Tu lis ce mail sur l’appareil où tu veux te connecter ? Le bouton fait la même
        chose.
      </P>
      <CTA href={url}>{cta}</CTA>
    </>
  );
}

/** « Changer d'adresse » (Mon espace › Compte): sent to the new address, which it confirms. */
export function emailChangeMail(p: { url: string; code: string }): Mail {
  return {
    subject: `${spaced(p.code)} · confirme ta nouvelle adresse sur notetonmaster`,
    element: (
      <Layout
        preview={`Ton code : ${spaced(p.code)}, valable 10 minutes.`}
        footer="Tu reçois ce mail parce que quelqu’un a demandé à utiliser cette adresse pour son espace notetonmaster. Si ce n’est pas toi, ignore-le : rien ne change."
      >
        <H1>Confirme ta nouvelle adresse</H1>
        <P>
          Tu te connecteras désormais avec cette adresse ; l’ancienne ne servira plus. Le code et le
          bouton ne fonctionnent qu’une fois : utiliser l’un désactive l’autre.
        </P>
        <CodeBlock code={p.code} url={p.url} cta="Confirmer sur cet appareil" />
      </Layout>
    ),
  };
}

export function magicLinkMail(p: { url: string; code: string; reviewPending?: boolean }): Mail {
  return {
    subject: p.reviewPending
      ? `Ton avis est en relecture · ton code de connexion ${spaced(p.code)}`
      : `${spaced(p.code)} · ton code de connexion à notetonmaster`,
    element: (
      <Layout
        preview={`Ton code : ${spaced(p.code)}, valable 10 minutes.`}
        footer="Tu reçois ce mail parce que quelqu’un a demandé à se connecter avec cette adresse. Si ce n’est pas toi, ignore-le : personne ne peut se connecter sans ce code."
      >
        <H1>{p.reviewPending ? 'Merci pour ton avis !' : 'Accède à ton espace'}</H1>
        {p.reviewPending && (
          <P>
            Ton avis est en relecture : une personne de l’équipe le lit sous 48 heures au plus. Tu
            recevras un mail quand il sera publié.
          </P>
        )}
        <CodeBlock code={p.code} url={p.url} cta="Se connecter sur cet appareil" />
        <P muted>
          Pas de mot de passe à retenir : à chaque connexion, on t’envoie un nouveau code.
        </P>
      </Layout>
    ),
  };
}

export function confirmReviewMail(p: { url: string; code: string; programTitle: string }): Mail {
  return {
    subject: `${spaced(p.code)} · confirme ton avis`,
    element: (
      <Layout
        preview={`Ton code : ${spaced(p.code)}, pour confirmer ton avis.`}
        footer="Tu reçois ce mail parce qu’un avis a été envoyé avec cette adresse. Si ce n’est pas toi, ignore-le : l’avis ne sera pas publié."
      >
        <H1>Confirme ton avis</H1>
        <P>
          Tu as donné ton avis sur le master <strong>{p.programTitle}</strong>. Confirme-le : il
          passera ensuite en relecture (48 heures au plus) et sera publié sans badge « Parcours
          vérifié ».
        </P>
        <CodeBlock code={p.code} url={p.url} cta="Confirmer sur cet appareil" />
        <P muted>Ton adresse n’est jamais affichée.</P>
      </Layout>
    ),
  };
}

/**
 * A review was sent for a parcours this address already reviewed. Said by mail only: the form
 * answers the same as for any review, so that nobody learns who wrote what.
 */
export function reviewDuplicateMail(p: {
  programTitle: string;
  needsEdit: boolean;
  spaceUrl: string;
}): Mail {
  return {
    subject: 'Tu as déjà un avis sur ce master',
    element: (
      <Layout
        preview="Un seul avis par parcours : le nouveau n’a pas été enregistré."
        footer="Tu reçois ce mail parce qu’un avis a été envoyé avec cette adresse. Si ce n’est pas toi, ignore-le : rien n’a été enregistré."
      >
        <H1>Tu as déjà un avis sur ce master</H1>
        <P>
          Un avis vient d’être envoyé avec cette adresse sur le master{' '}
          <strong>{p.programTitle}</strong>. Tu en as déjà un sur ce parcours : on garde un seul
          avis par parcours, le nouveau n’a donc pas été enregistré.
        </P>
        <P>
          {p.needsEdit
            ? 'Ton avis attend une reformulation : modifie-le depuis ton espace.'
            : 'Pour changer ton avis, modifie-le depuis ton espace.'}
        </P>
        <P>
          <a href={p.spaceUrl}>Ouvrir mon espace</a>
        </P>
      </Layout>
    ),
  };
}

/** An admin account logged in from a device never seen before. */
export function newDeviceMail(p: { name: string; userAgent: string | null; at: Date }): Mail {
  const when = p.at.toLocaleString('fr-FR', {
    timeZone: 'Europe/Paris',
    dateStyle: 'long',
    timeStyle: 'short',
  });
  return {
    subject: 'Nouvelle connexion à ton compte d’administration',
    element: (
      <Layout
        preview={`Connexion depuis un nouvel appareil le ${when}.`}
        footer="Tu reçois ce mail à chaque connexion à l’administration depuis un appareil inconnu."
      >
        <H1>Nouvelle connexion</H1>
        <P>
          Bonjour {p.name}, ton compte d’administration vient d’être utilisé depuis un appareil
          qu’on ne connaissait pas, le {when}.
        </P>
        {p.userAgent && <P muted>Navigateur : {p.userAgent}</P>}
        <P>
          Si c’est toi, il n’y a rien à faire. Sinon, préviens tout de suite un·e admin : ton mot de
          passe et ta double authentification sont à changer.
        </P>
      </Layout>
    ),
  };
}

export type ReviewDecision = 'PUBLISHED' | 'NEEDS_EDIT' | 'REJECTED' | 'HIDDEN';

export function reviewDecisionMail(p: {
  decision: ReviewDecision;
  programTitle: string;
  reviewTitle: string | null;
  reason?: string | null;
  hasAccount: boolean;
  programUrl: string;
}): Mail {
  const t = p.reviewTitle ? ` « ${p.reviewTitle} »` : '';
  const copy = {
    PUBLISHED: {
      subject: 'Ton avis est publié',
      h: 'Ton avis est en ligne',
      body: `Ton avis${t} sur ${p.programTitle} a été relu et publié. Merci, il aidera la promo d’après.`,
    },
    NEEDS_EDIT: {
      subject: 'Ton avis est à reformuler',
      h: 'Une petite reformulation',
      body: `Ton avis${t} sur ${p.programTitle} ne peut pas être publié tel quel.`,
    },
    REJECTED: {
      subject: 'Ton avis n’a pas été publié',
      h: 'Ton avis n’a pas été publié',
      body: `Ton avis${t} sur ${p.programTitle} n’a pas été publié.`,
    },
    HIDDEN: {
      subject: 'Ton avis est masqué',
      h: 'Ton avis est masqué',
      body: `Ton avis${t} sur ${p.programTitle} a été retiré du site.`,
    },
  }[p.decision];
  return {
    subject: copy.subject,
    element: (
      <Layout preview={copy.body}>
        <H1>{copy.h}</H1>
        <P>{copy.body}</P>
        {p.reason && (
          <>
            <P muted>Motif communiqué par la modération :</P>
            <Quote>{p.reason}</Quote>
          </>
        )}
        {p.decision === 'PUBLISHED' && <CTA href={p.programUrl}>Voir la fiche</CTA>}
        {p.decision === 'NEEDS_EDIT' &&
          (p.hasAccount ? (
            <CTA href={`${appUrl()}/espace/avis`}>Reformuler mon avis</CTA>
          ) : (
            <P>Tu peux renvoyer un avis reformulé depuis le formulaire, avec la même adresse.</P>
          ))}
        <P muted>
          Tu peux contester cette décision en écrivant via la page À propos. Les décisions suivent
          la charte de modération.
        </P>
      </Layout>
    ),
  };
}

export function verificationCodeMail(p: { code: string }): Mail {
  return {
    subject: `Ton code de vérification : ${p.code}`,
    element: (
      <Layout
        preview={`Code ${p.code}, valable 15 minutes.`}
        footer="Tu reçois ce mail parce que cette adresse universitaire a été saisie pour obtenir le badge « Parcours vérifié ». On ne garde qu’une empreinte de l’adresse."
      >
        <H1>Ton code de vérification</H1>
        <P>
          Saisis ce code dans ton espace pour obtenir le badge « Parcours vérifié ». Il est valable
          15 minutes.
        </P>
        <Code>{p.code}</Code>
        <P muted>Si tu n’as rien demandé, ignore ce mail.</P>
      </Layout>
    ),
  };
}

export function verificationResultMail(p: {
  approved: boolean;
  moreInfo?: boolean;
  reason?: string | null;
}): Mail {
  const subject = p.approved
    ? 'Ton parcours est vérifié'
    : p.moreInfo
      ? 'Il nous faut un autre justificatif'
      : 'Ton justificatif n’a pas été accepté';
  return {
    subject,
    element: (
      <Layout preview={subject}>
        <H1>{subject}</H1>
        <P>
          {p.approved
            ? 'Tes avis portent maintenant le badge « Parcours vérifié ». Ton document a été supprimé : on garde seulement la date de vérification.'
            : 'Ton document a été supprimé, comme prévu. Tes avis restent publiés, sans badge.'}
        </P>
        {p.reason && <Quote>{p.reason}</Quote>}
        <CTA href={`${appUrl()}/espace/verification`}>
          {p.approved ? 'Voir mon espace' : 'Envoyer un autre justificatif'}
        </CTA>
      </Layout>
    ),
  };
}

/**
 * Anonymous messaging: the Reply-To of every mail is the team (lib/mail/send.ts). Answering the
 * mail would reach the team, not the other person, and give the team the sender's address.
 */
function AnonymousReplyWarning() {
  return (
    <P muted>
      <strong>Ne réponds pas à ce mail</strong> : ta réponse arriverait à l’équipe du site, pas à
      ton interlocuteur·rice, avec ton adresse. Pour lui écrire, passe par le bouton ci-dessus.
    </P>
  );
}

export function questionReceivedMail(p: {
  programTitle: string;
  universityName: string;
  reviewTitle: string | null;
  question: string;
  replyUrl: string;
  hasAccount: boolean;
}): Mail {
  return {
    subject: 'Quelqu’un te demande de l’aide sur ton avis',
    element: (
      <Layout
        preview={p.question.slice(0, 120)}
        footer={
          <>
            Tu reçois ce mail parce que tu as accepté que des étudiant·es te posent des questions
            sur tes avis.{' '}
            {p.hasAccount ? (
              <a href={`${appUrl()}/espace/compte`}>Ne plus recevoir de questions</a>
            ) : null}
          </>
        }
      >
        <H1>Quelqu’un te demande de l’aide</H1>
        <P>
          Un·e étudiant·e qui s’intéresse au master <strong>{p.programTitle}</strong> (
          {p.universityName}) a lu ton avis{p.reviewTitle ? ` « ${p.reviewTitle} »` : ''} et te pose
          une question :
        </P>
        <Quote>« {p.question} »</Quote>
        <CTA href={p.replyUrl}>Répondre anonymement</CTA>
        <P muted>
          Ton adresse n’a pas été partagée, et tu ne vois pas la sienne. Tu n’es pas obligé·e de
          répondre.
          {p.hasAccount ? '' : ' Le lien de réponse est valable 7 jours et ne sert qu’une fois.'}
        </P>
        <AnonymousReplyWarning />
      </Layout>
    ),
  };
}

export function replyReceivedMail(p: {
  programTitle: string;
  reply: string;
  url: string;
  hasAccount: boolean;
  fromAuthor: boolean;
}): Mail {
  return {
    subject: p.fromAuthor ? 'Tu as reçu une réponse à ta question' : 'Nouveau message sur ton avis',
    element: (
      <Layout
        preview={p.reply.slice(0, 120)}
        footer="Tu reçois ce mail parce que tu participes à une conversation anonyme sur notetonmaster."
      >
        <H1>{p.fromAuthor ? 'Tu as une réponse' : 'Nouveau message'}</H1>
        <P>
          {p.fromAuthor ? 'L’auteur·rice de l’avis' : 'La personne qui t’a posé une question'} sur
          le master <strong>{p.programTitle}</strong> t’a écrit :
        </P>
        <Quote>« {p.reply} »</Quote>
        <CTA href={p.url}>{p.hasAccount ? 'Voir la conversation' : 'Répondre'}</CTA>
        <P muted>
          Vous restez anonymes l’un pour l’autre.{' '}
          {p.hasAccount ? '' : 'Le lien est valable 7 jours et ne sert qu’une fois.'}
        </P>
        <AnonymousReplyWarning />
      </Layout>
    ),
  };
}

export function reportAckMail(p: { reference: string; formal: boolean; deadline?: Date }): Mail {
  return {
    subject: p.formal ? `Notification reçue · ${p.reference}` : `Signalement reçu · ${p.reference}`,
    element: (
      <Layout preview={`Référence ${p.reference}`}>
        <H1>{p.formal ? 'Ta notification est bien reçue' : 'Merci pour ton signalement'}</H1>
        <P>
          Référence : <strong>{p.reference}</strong>. Une personne de l’équipe examine{' '}
          {p.formal ? 'ta notification' : 'ton signalement'} au regard de la charte de modération et
          de la loi.
        </P>
        <P>
          {p.formal
            ? `Tu recevras une décision motivée${p.deadline ? ` au plus tard le ${p.deadline.toLocaleDateString('fr-FR')}` : ''}. L’auteur du contenu en est également informé.`
            : 'Si l’avis enfreint la charte, il sera retiré. On te tiendra au courant de la décision.'}
        </P>
      </Layout>
    ),
  };
}

