/** Questions publiques: weekly digest to the verified alumni of a master. */
export function questionDigestMail(p: {
  programTitle: string;
  url: string;
  questions: string[];
  settingsUrl: string;
}): Mail {
  const n = p.questions.length;
  return {
    subject: `${n} question${n > 1 ? 's' : ''} sans réponse sur ${p.programTitle}`,
    element: (
      <Layout
        preview="Ton expérience peut aider la promo d’après."
        footer="Tu reçois ce récapitulatif (une fois par semaine au plus) parce que ton parcours est vérifié et que tu acceptes les questions."
      >
        <H1>On pose des questions sur ton master</H1>
        <P>
          {n > 1 ? 'Ces questions attendent' : 'Cette question attend'} une réponse sur{' '}
          <strong>{p.programTitle}</strong> :
        </P>
        {p.questions.slice(0, 5).map((q) => (
          <Quote key={q}>{q}</Quote>
        ))}
        <CTA href={p.url}>Répondre</CTA>
        <P muted>
          Ta réponse est publiée sous ton niveau et ta promo, sans ton nom, après relecture.{' '}
          <a href={p.settingsUrl}>Ne plus recevoir ce récapitulatif</a>
        </P>
      </Layout>
    ),
  };
}

